SELECT "list_user_order_totals"."user_id", "list_user_order_totals"."name", "list_user_order_totals"."order_count", "list_user_order_totals"."total" FROM (SELECT u.id AS user_id, u.name, count(o.id) AS order_count, COALESCE(sum(o.amount), 0)::numeric AS total FROM users u LEFT JOIN orders o ON o.user_id = u.id WHERE u.created_at >= $1 AND u.status = $2 GROUP BY u.id, u.name) AS "list_user_order_totals" WHERE "list_user_order_totals"."order_count" > $3 ORDER BY "list_user_order_totals"."total" DESC LIMIT $4
-- args: []interface {}{pgtype.Timestamptz{Time:time.Date(1, time.January, 1, 0, 0, 0, 0, time.UTC), InfinityModifier:0, Valid:false}, "active", 2, 10}
